import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("should return a premium of 5 G for an empty item list (processing fee only)");
    it.todo("should charge 100 G base premium for a sword");
    it.todo("should charge 60 G base premium for an amulet");
    it.todo("should charge 80 G base premium for a staff");
    it.todo("should charge 40 G base premium for a potion");
    it.todo("should sum the base premiums of several main items");
  });

  describe("quote — components and building blocks", () => {
    it.todo("should charge 25 G base premium per single component");
    it.todo("should charge 50 G base premium for 2 runes");
    it.todo("should charge 60 G base premium for exactly 3 runes (block applies)");
    it.todo("should charge 100 G base premium for 4 runes (no block, block requires exactly 3)");
    it.todo("should charge 175 G base premium for 7 runes (no block)");
    it.todo("should charge 75 G base premium for 2 runes and 1 moonstone (no block: different types)");
    it.todo("should charge 120 G base premium for 3 runes and 3 moonstones (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("should add 50 % of the item's base premium for a cursed item");
    it.todo("should add 30 % of the item's base premium for enchantment level 5");
    it.todo("should not add the high-enchantment surcharge for enchantment level 4");
    it.todo("should add both surcharges for a cursed item with enchantment level 5");
    it.todo("should apply the cursed surcharge only to the cursed item's base premium in a multi-item policy (cursed sword + plain amulet)");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("should add 10 % first insurance surcharge per item on every quote");
    it.todo("should subtract 20 % loyalty discount for a customer with 2 years with MHPCO");
    it.todo("should not apply the loyalty discount for a customer with 1 year with MHPCO");
    it.todo("should subtract 15 % follow-up discount on the customer's second quote");
    it.todo("should not apply the follow-up discount on the customer's first quote");
    it.todo("should add the 5 G processing fee at the very end");
    it.todo("should round the final premium up (197.5 G becomes 198 G)");
  });

  describe("quote — integration examples", () => {
    it.todo("should charge 165 G for a newcomer's cursed steel sword with enchantment 3");
    it.todo("should charge 160 G for a 3-year customer's second quote of a cursed steel sword with enchantment 7");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("should pay 400 G for 500 G damage to a regular sword (deductible of 100 G)");
    it.todo("should pay 100 G for 200 G damage to a rune (no enchantment level or material)");
    it.todo("should apply the 100 G deductible once per damage entry (sword 500 G + amulet 300 G pays 600 G)");
    it.todo("should round the final payout down (350.5 G becomes 350 G)");
  });

  describe("claim — special clauses", () => {
    it.todo("should reimburse 50 % before the deductible for enchantment level 8 (1000 G damage pays 400 G)");
    it.todo("should fully reimburse dragon material before the deductible (800 G damage pays 700 G)");
    it.todo("should apply the 50 % rule for a steel sword with enchantment 9 (1000 G damage pays 400 G)");
    it.todo("should let the 50 % rule win over dragon material when both apply (dragon sword, enchantment 9, 1000 G damage pays 400 G)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("should cap the payout at twice the insurance sum of the policy");
    it.todo("should report the remaining cap after a claim");
    it.todo("should base the insurance sum on the items' insurance values (sword + amulet = 1600 G, cap 3200 G)");
    it.todo("should not raise the cap through premium modifiers (cursed sword still has cap 2000 G)");
    it.todo("should not reduce the insurance sum through the component block discount (sword + 3 runes = 1750 G)");
    it.todo("should use the insurance sum of both swords for a policy covering two swords (2000 G, cap 4000 G)");
    it.todo("should reduce a later payout to the remaining cap (two 1500 G claims on a sword pay 1400 G then 600 G)");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("should treat two damage entries of the same item type as separate damages with their own deductible");
  });

  describe("errors", () => {
    it.todo("should reject a quote containing an item with an unknown type");
    it.todo("should reject a claim whose damage references an item type not covered by the policy");
    it.todo("should reject a claim whose damage references an unknown item type");
    it.todo("should reject a claim with more damage entries of a type than the policy insures");
    it.todo("should reject a claim with a negative damage amount");
  });
});
